    for (let i = 0; i < 3 + n; i++) oval(ctx, 65 + Math.cos(i * 1.2) * 10, 70 + Math.sin(i * 1.2) * 9, 1.9, 1.9, '#69558b');
    line(ctx, [[29, 95], [41 + n * 3, 100], [80, 91]], accent, 2);
