    if(activeMode==='snake'||activeMode==='2048'||activeMode==='match3'||activeMode==='plinko'||activeMode==='simon'||activeMode==='duck'||activeMode==='slots'||(e.code!=='Space'&&e.code!=='ArrowUp')||e.target!==canvas)return;
